        SObject before;
        SObject attempted;
        String relationshipName;
        Schema.SObjectField fieldToken;
        Boolean token = false;
        Boolean metadata = row.startsWith('M');
        String phase = 'setup';
        try {
            if (row == 'S01' || row == 'S02' || row == 'S03' || row == 'S04' || row == 'S10') {
                record = new Contact(); before = new Account(Name='before');
                relationshipName = 'Account'; fieldToken = Contact.AccountId;
                token = row == 'S03' || row == 'S04';
                if (row == 'S01' || row == 'S03') attempted = new User(LastName='after');
                else if (row != 'S10') attempted = new Account(Name='after');
            } else if (row == 'S05' || row == 'S06') {
                record = new PutChild__c(); before = new PutParent__c(Name='before');
                relationshipName = 'ParentLink__r';
